{

    internal InnerFirewallRuleGroupFirewallAdvancedThreatCategoryConfigFactory FirewallAdvancedThreatCategoryFactory { get; set; }

    internal InnerFirewallRuleGroupPartnerThreatProtectionConfigFactory PartnerThreatProtectionFactory { get; set; }

    internal InnerFirewallRuleGroupFirewallAdvancedContentCategoryConfigFactory FirewallAdvancedContentCategoryFactory { get; set; }

    protected override Humidifier.Route53Resolver.FirewallRuleGroupTypes.FirewallRuleType Create()
    {
        var firewallRuleTypeResult = CreateFirewallRuleType();
        factoryAction?.Invoke(firewallRuleTypeResult);

        return firewallRuleTypeResult;
    }

    private Humidifier.Route53Resolver.FirewallRuleGroupTypes.FirewallRuleType CreateFirewallRuleType()
    {
        var firewallRuleTypeResult = new Humidifier.Route53Resolver.FirewallRuleGroupTypes.FirewallRuleType();

        return firewallRuleTypeResult;
    }
    public override void CreateChildren(Humidifier.Route53Resolver.FirewallRuleGroupTypes.FirewallRuleType result)
    {
        base.CreateChildren(result);

        result.FirewallAdvancedThreatCategory ??= FirewallAdvancedThreatCategoryFactory?.Build();
        result.PartnerThreatProtection ??= PartnerThreatProtectionFactory?.Build();
        result.FirewallAdvancedContentCategory ??= FirewallAdvancedContentCategoryFactory?.Build();
    }

} // End Of Class

